export default function SeedDataPage() {
  const [status, setStatus] = useState('')
  const [done, setDone] = useState(false)

  async function load() {
    setStatus('Loading...')
    const sb = createClient()
    const ts = new Date().toISOString()
    for (const [key, data] of [['ma_data', MA_DATA], ['prev_year_data', PREV_DATA], ['weekly_data', WEEKLY_DATA]] as const) {
      setStatus(`Writing ${key}...`)
      const { error } = await sb.from('production_state').upsert({ key, data, updated_at: ts })
      if (error) { setStatus(`ERROR on ${key}: ${error.message}`); return }
    }
    setStatus(`Done! ${MA_DATA.length} MAs, ${PREV_DATA.length} prev-year, ${WEEKLY_DATA.length} weeks loaded.`)
    setDone(true)
  }

  return (
    <div style={{ padding: 48, fontFamily: 'sans-serif', maxWidth: 600 }}>
      <h2>Load App Data into Supabase</h2>
      <p>This will write SG + D2C apps from both 2025 and 2026 CSVs, plus seed production numbers.</p>
      <ul>
        <li><strong>30</strong> MA records (2026)</li>
        <li><strong>32</strong> prev-year records (2025)</li>
        <li><strong>32</strong> weekly buckets</li>
      </ul>
      <button
        onClick={load}
        disabled={done}
        style={{ padding: '12px 28px', fontSize: 16, background: done ? '#16a34a' : '#1e3a5f',
          color: '#fff', border: 'none', borderRadius: 8, cursor: done ? 'default' : 'pointer' }}
      >
        {done ? '✓ Done' : 'Load Data Now'}
      </button>
      {status && <p style={{ marginTop: 16, color: done ? '#16a34a' : '#555' }}>{status}</p>}
      {done && <p><a href="/">← Back to app</a></p>}
    </div>
  )
}
